SELECT section, line, direction, COUNT(*) total,
       SUM(latitude IS NOT NULL AND longitude IS NOT NULL) AS with_ll
FROM div_signals WHERE is_active=1 AND section IN ('KYN-KJT','KYN-KSRA')
GROUP BY section, line, direction ORDER BY section, line, direction;
